import java.util.*;

public class Main {
    int MOD = 1_000_000_007;

    int totalStrength(int[] strength) {
        int n = strength.length;
        long[] prefix = new long[n + 1];                                              // prefix[k] = sum of strength[0..k-1]
        for (int i = 0; i < n; i++) prefix[i + 1] = (prefix[i] + strength[i]) % MOD;

        long[] prefixOfPrefix = new long[n + 2];                                       // prefixOfPrefix[k] = sum of prefix[0..k-1]
        for (int i = 0; i <= n; i++) prefixOfPrefix[i + 1] = (prefixOfPrefix[i] + prefix[i]) % MOD;

        int[] left = new int[n];                                                       // nearest index to the left with a STRICTLY smaller value
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && strength[stack.peek()] >= strength[i]) stack.pop();
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        int[] right = new int[n];                                                     // nearest index to the right with a value <= strength[i]
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && strength[i] < strength[stack.peek()]) stack.pop();
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        long total = 0;
        for (int i = 0; i < n; i++) {
            int l = left[i], r = right[i];
            long leftCount = i - l;                                                        // number of valid LEFT edges for subarrays where i is the min
            long rightCount = r - i;                                                       // number of valid RIGHT edges
            long sumOfEndTerms = ((prefixOfPrefix[r + 1] - prefixOfPrefix[i + 1]) % MOD + MOD) % MOD;
            long sumOfStartTerms = ((prefixOfPrefix[i + 1] - prefixOfPrefix[l + 1]) % MOD + MOD) % MOD;
            long combined = ((leftCount * sumOfEndTerms - rightCount * sumOfStartTerms) % MOD + MOD) % MOD;
            total = (total + strength[i] * combined) % MOD;
        }
        return (int) total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] a = {1, 3, 1, 2};
        int[] b = {5, 4, 6};
        System.out.println(solution.totalStrength(a));
        System.out.println(solution.totalStrength(b));
    }
}

