#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1e9 + 7;

int totalStrength(vector<int>& strength) {
    int n = strength.size();
    vector<long long> prefix(n + 1, 0);                                                  // prefix[k] = sum of strength[0..k-1]
    for (int i = 0; i < n; i++) prefix[i + 1] = (prefix[i] + strength[i]) % MOD;

    vector<long long> prefixOfPrefix(n + 2, 0);                                          // prefixOfPrefix[k] = sum of prefix[0..k-1]
    for (int i = 0; i <= n; i++) prefixOfPrefix[i + 1] = (prefixOfPrefix[i] + prefix[i]) % MOD;

    vector<int> left(n, -1);                                                             // nearest index to the left with a STRICTLY smaller value
    vector<int> stack;
    for (int i = 0; i < n; i++) {
        while (!stack.empty() && strength[stack.back()] >= strength[i]) stack.pop_back();
        left[i] = stack.empty() ? -1 : stack.back();
        stack.push_back(i);
    }

    vector<int> right(n, n);                                                            // nearest index to the right with a value <= strength[i]
    stack.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.empty() && strength[i] < strength[stack.back()]) stack.pop_back();
        right[i] = stack.empty() ? n : stack.back();
        stack.push_back(i);
    }

    long long total = 0;
    for (int i = 0; i < n; i++) {
        int l = left[i], r = right[i];
        long long leftCount = i - l;                                                         // number of valid LEFT edges for subarrays where i is the min
        long long rightCount = r - i;                                                        // number of valid RIGHT edges
        long long sumOfEndTerms = ((prefixOfPrefix[r + 1] - prefixOfPrefix[i + 1]) % MOD + MOD) % MOD;
        long long sumOfStartTerms = ((prefixOfPrefix[i + 1] - prefixOfPrefix[l + 1]) % MOD + MOD) % MOD;
        long long combined = ((leftCount * sumOfEndTerms - rightCount * sumOfStartTerms) % MOD + MOD) % MOD;
        total = (total + (long long)strength[i] * combined) % MOD;
    }
    return (int)total;
}

int main() {
    vector<int> a = {1, 3, 1, 2};
    vector<int> b = {5, 4, 6};
    cout << totalStrength(a) << endl;
    cout << totalStrength(b) << endl;
    return 0;
}
